#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
    Velocity's REST api documentation parser.
"""

__author__ = "Velocity Support"
__email__ = "velocity.support@nokia.com"

import os
import sys

import service as velocity_service

try:
    import lib.requests as requests
    from lib.bs4_py3 import BeautifulSoup
except ImportError:
    sys.path.insert(0, os.path.abspath(os.path.join(os.path.pardir, '../')))
    import lib.requests as requests
    from lib.bs4_py3 import BeautifulSoup
requests.packages.urllib3.disable_warnings(
    requests.packages.urllib3.exceptions.InsecureRequestWarning
)


if __name__ == "__main__":
    with open('api_doc.html', 'r', encoding="utf8") as f:
        resp = f.read()
    soup = BeautifulSoup(resp, features='lxml')

    # response = requests.get(
    #     "https://10.34.180.112/velocity/api/doc", verify=False
    # )
    # soup = BeautifulSoup(response.text, features='lxml')

    services_field = soup.find('div', {"class": "col-md-9"})
    services = services_field.find_all("div", {"class": "panel panel-default"})
    func_count = 0

    for service_tag in services:
        service = velocity_service.CService(service_tag)
        service.parse()
    # print("Services count: ", len(services))
    # print("Funcs count: ", func_count)
